    label: "PAPER / SIMULATED \u2014 no real money",
    segments: paperSegments(trades, AGENTS, INSTRUMENTS),
    valuation: await valuationFor(env, portfolio, trades),
    scheduler: await schedulerHealth(env),
    researchVersion: RESEARCH_VERSION,
    equityPeak: portfolio.equityPeak || portfolio.startingBalance,
    currentDrawdownPct: 100 * Math.max(0, 1 - (await valuationFor(env, portfolio, trades)).equity / (portfolio.equityPeak || portfolio.startingBalance)),
    decisions: (await readCappedLog(env, "paper:decisions")).slice(-100).reverse(),
    startingBalance: portfolio.startingBalance,
    currentCash: portfolio.cash,
    openPositions,
    today: {
      date: today3,
      pnl: todayPnl,
      trades: todayTrades.length,
      wins,
      losses,
      winRatePct: todayTrades.length ? wins / todayTrades.length * 100 : null,
      lostMoneyToday: todayPnl < 0
    },
    allTime: {
      pnl: totalPnl,
      trades: trades.length,
      wins: totalWins,
      winRatePct: trades.length ? totalWins / trades.length * 100 : null
    },
    recentTrades: trades.slice(-10).reverse(),
    stats,
    // Phase 4.3: per-councillor stats (win rate, avg win/loss, max drawdown, Sharpe-style), PAPER
    agents: Object.fromEntries(Object.values(AGENTS).map((a) => [
      a.id,
      { label: a.label, name: a.name, theme: a.theme || null, hoursNote: INSTRUMENTS[a.instrumentId].hoursNote }
    ]))
