// src/lib/tools.js
async function executeTool(env, name, input, personaId = DEFAULT_PERSONA_ID, ctx = {}) {
  const startedAt = Date.now();
  let success = true;
  let error = null;
  try {
    return await runTool(env, name, input, personaId, ctx);
  } catch (err) {
    success = false;
    error = err.message;
    throw err;
  } finally {
    void appendCappedLog(env, TASK_LOG_KEY, {
      time: new Date(startedAt).toISOString(),
      tool: name,
      persona: personaId,
      durationMs: Date.now() - startedAt,
      success,
      error
    }, TASK_LOG_CAP).catch((err) => console.error("task log write failed:", err && err.message));
  }
}
async function getTaskLog(env) {
  return await readCappedLog(env, TASK_LOG_KEY);
}
